function codeLesson(track,id,title,intro,concept,example,explain,task,solution,test,hint,reflection,kind='javascript'){
 LESSONS.push({track,id,title,minutes:25,kind,intro,concept,example,explain,steps:[task.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'),'先预测输出，再运行。根据错误中的行号修改，不要直接复制参考答案。','完成后改一个输入，解释结果为什么变化。'],starter:'// '+task+'\n',solution,test,hint,reflection});
}
codeLesson('javascript','js-01','第一次让网页程序说话','JavaScript 是一种编程语言。浏览器用它处理点击和数据；这一课只学习显示一句话。','console.log() 把括号中的值写到输出区。字符串要用英文引号；分号表示一条语句结束。// 后面是给人看的注释。','console.log("你好，网页！");','console 是一个提供输出方法的对象，log 是它的一个方法。点号表示取出对象中的成员。这个练习不需要理解所有对象细节。','输出文字：你好，JavaScript！','console.log("你好，JavaScript！");','assert(true);','输入 console.log("你好，JavaScript！");。检查器会核对输出文字是否完全一致。','去掉引号后为什么会寻找变量？为什么输出区不是网页页面？');
// The first exercise grades actual output rather than just successful execution.
LESSONS.at(-1).test='assert(_output().trim() === "你好，JavaScript！", "请输出指定问候语");';
codeLesson('javascript','js-02','变量、数值与字符串','变量像给数据贴名字。价格和数量先分别保存，再计算总价。','const 声明不能重新赋值的名称；let 声明可以重新赋值的名称。数值 3 与字符串 "3" 不同；加号遇到字符串可能拼接。','const price = 8;\nlet count = 2;\nconsole.log(price * count);','price 保存 8；count 保存 2；乘法得到 16。const 不代表对象内部永远不可变，后面会验证这一点。','定义函数 total(price, count)，返回两数乘积。','function total(price, count) { return price * count; }\nconsole.log(total(8, 2));','assert(total(8,2)===16); assert(total(5,0)===0); assert(total(2.5,4)===10);','函数格式：function 名称(参数) { return 结果; }','如果 price 来自输入框且是字符串，应在哪一层转换和校验？');
codeLesson('javascript','js-03','判断与明确的边界','电脑不会自动理解“成年”。你要明确写出年龄分界。','if 在条件为真时进入代码块；else 处理另一种情况。=== 严格比较值和类型；>= 包含等号边界。','function label(age) {\n  if (age >= 18) return "成年";\n  return "未成年";\n}','return 会立即结束当前函数，因此满足第一条条件后，不会继续执行第二个 return。','实现 canRegister(age)：只有 18 到 120（含边界）返回 true，其他返回 false。','function canRegister(age) { return age >= 18 && age <= 120; }','assert(canRegister(18)===true);assert(canRegister(120)===true);assert(canRegister(17)===false);assert(canRegister(121)===false);','&& 表示两个条件都成立。','为什么只测试 30 岁无法发现把 >= 写成 > 的错误？');
codeLesson('javascript','js-04','数组、循环与空列表','数组保存有顺序的一组值。用循环处理每一项，不必复制同一行计算。','[] 创建数组；for...of 按顺序取出每个元素。累加变量从 0 开始，每次更新它。','let sum = 0;\nfor (const n of [2, 4, 6]) { sum += n; }\nconsole.log(sum);','sum += n 等价于 sum = sum + n。空数组不会执行循环体，所以正确初始值很重要。','实现 sumPositive(values)，只累加大于 0 的数字。','function sumPositive(values) { let total=0; for(const n of values) { if(n>0) total+=n; } return total; }','assert(sumPositive([2,-3,4])===6);assert(sumPositive([])===0);assert(sumPositive([-2,0])===0);','先写空列表返回 0，再写循环和条件。','如何用一个全负数输入验证“只累加正数”？');
codeLesson('javascript','js-05','对象与不偷偷改动原数据','任务有标题、状态等字段，适合放进一个对象。','对象用键值对描述事物。点号读取属性；展开语法 ... 复制一层属性。复制一层不等于深拷贝。','const task = {title:"练习", done:false};\nconst next = {...task, done:true};\nconsole.log(task.done, next.done);','next 是新对象；done 覆盖为 true；旧 task.done 仍是 false。嵌套对象仍可能共享引用。','实现 complete(task)，返回 done 为 true 的新对象，保留其他字段且不修改传入对象。','function complete(task) { return {...task, done:true}; }','const item={title:"A",done:false,id:7};const next=complete(item);assert(next!==item);assert(item.done===false);assert(next.done===true&&next.id===7&&next.title==="A");','不要写 task.done = true。先复制再覆盖。','如果 task.meta 是对象，这个复制能防止修改 meta 吗？');
codeLesson('javascript','js-06','函数、作用域与闭包','函数可以记住创建它时所在环境中的变量。这叫闭包。','函数里的局部变量不能从外面直接访问；返回的内部函数仍能访问它。不同调用创建独立的环境。','function makeCounter() {\n let n=0;\n return () => ++n;\n}\nconst next=makeCounter();\nconsole.log(next(), next());','箭头函数 () => ++n 没有参数，返回增加后的值。这里记住的是变量 n，不是某一次 n 的快照。','实现 makeCounter()，每个计数器从 1 开始，每次调用增加 1，互不干扰。','function makeCounter() { let n=0; return () => ++n; }','const a=makeCounter(),b=makeCounter();assert(a()===1);assert(a()===2);assert(b()===1);assert(a()===3);','n 必须放在 makeCounter 内部，不能用全局共享变量。','一个网页创建两个独立计时器时，共享全局变量会怎样？');
codeLesson('javascript','js-07','map、filter 与回调函数','把函数当参数传入，是 JavaScript 常见写法。','filter 保留条件为真的项；map 把每项转换成新值。它们返回新数组，不会自动修改原数组。','const names=[{name:"A",active:true},{name:"B",active:false}]\n .filter(user => user.active)\n .map(user => user.name);','user => user.active 是一个函数：输入 user，返回 active 属性。链式调用的下一步处理上一步的结果。','实现 activeNames(users)，按原顺序返回 active 严格为 true 的用户姓名。','function activeNames(users) { return users.filter(u=>u.active===true).map(u=>u.name); }','assert(JSON.stringify(activeNames([{name:"A",active:true},{name:"B",active:false},{name:"C",active:true}]))===JSON.stringify(["A","C"]));assert(activeNames([]).length===0);assert(activeNames([{name:"X",active:"false"}]).length===0);','用 === true 避免字符串 "false" 被当成真。','map 与 forEach 的返回值有何区别？');
codeLesson('javascript','js-08','错误、异常与可恢复失败','输入不合法时，返回一个正常数字会掩盖问题。','throw 抛出错误；try/catch 捕获错误。只捕获你知道如何处理的错误，不要空 catch 静默忽略。','function divide(a,b) {\n if(b===0) throw new Error("不能除以零");\n return a/b;\n}','new Error 保存错误说明；抛出后本函数后续语句不再执行。调用者决定显示提示还是终止。','实现 divide(a,b)；b 为 0 时抛出 Error，否则返回商。','function divide(a,b) { if(b===0) throw new Error("不能除以零"); return a/b; }','assert(divide(8,2)===4);assert(divide(0,3)===0);let caught=false;try{divide(1,0)}catch(e){caught=e instanceof Error}assert(caught,"零除必须抛出错误");','测试错误路径时，用 try/catch 设置 caught。','异常信息里可以放密码或完整用户数据吗？为什么？');
codeLesson('javascript','js-09','Promise、await 与顺序','网络响应需要等待，但等待不等于让所有网页操作都停下来。','Promise 表示未来可能成功或失败的结果。async 函数总返回 Promise；await 等结果，拒绝会作为异常抛出。','async function twice(load) {\n const value = await load();\n return value * 2;\n}\nconsole.log(await twice(() => Promise.resolve(3)));','load 是传入的函数，所以测试可以提供假数据，不必访问真实网络。这也是依赖注入的一种形式。','实现 async function loadTotal(load)，await load() 得到数字数组，返回总和；失败应向上传递。','async function loadTotal(load) { const values=await load(); return values.reduce((a,b)=>a+b,0); }','assert(await loadTotal(()=>Promise.resolve([2,3]))===5);assert(await loadTotal(()=>Promise.resolve([]))===0);let caught=false;try{await loadTotal(()=>Promise.reject(new Error("offline")))}catch{caught=true}assert(caught);','先 await 再处理数组；不要把失败伪装成成功的 0。','并行请求和串行 await 各在什么时候合适？');
function guidedNew(track,id,title,intro,concept,example,explain,steps,checks,q,options,answer,reflection,source){
 guide({track,id,title,intro,concept,example,explain,steps,checks,quiz:{q,options,answer,explanation:options[answer]},hint:'先只执行第一步，记录预期与实际结果；遇到错误，保留完整错误和执行位置，再缩小到最小例子。',reflection,source});
}
guidedNew('javascript','js-10','DOM 与事件：点击后发生什么','DOM 是浏览器对页面结构的对象表示。这里要在本机建立真正的 HTML 文件。','querySelector 找元素；addEventListener 订阅事件；textContent 写入文字。把输入当文字显示，可避免把它当 HTML 执行。','<!doctype html><meta charset="utf-8">\n<input id="name" aria-label="姓名"><button id="say">问候</button><p id="out"></p>\n<script>\n document.querySelector("#say").addEventListener("click",()=>{\n  document.querySelector("#out").textContent="你好，"+document.querySelector("#name").value;\n });\n</script>','脚本在元素之后运行，查询时元素已存在。回调在点击时执行，不是在绑定时立即执行。',['创建 hello.html，粘贴示例并用浏览器打开。','输入名字并点击；再输入 <b>测试</b>，应该显示原样文字。','加入空白输入判断；按回车也能触发，说明要监听哪个事件。'],['真实打开 HTML 并点击','输入标签仍显示为文字','能从事件追到 DOM 更新'],'为什么优先用 textContent 显示用户输入？',['让输入作为文字，不解析成 HTML','自动连接数据库','能证明后端没有漏洞'],0,'重复绑定同一个事件会造成什么现象？','https://developer.mozilla.org/zh-CN/docs/Web/API/Document_Object_Model');
guidedNew('javascript','js-11','模块、fetch 与失败状态','应用变大后，把数据处理和页面显示分开，才能分别测试。','export 导出成员，import 引入成员。fetch 的 HTTP 404 通常不会自动 reject，必须检查 response.ok。浏览器跨域请求还受 CORS 限制。','export async function loadTasks(fetcher, url) {\n const response=await fetcher(url);\n if(!response.ok) throw new Error(`HTTP ${response.status}`);\n return response.json();\n}','注入 fetcher 允许测试传入模拟响应；生产调用 loadTasks(fetch, "/api/tasks")。文件模块应通过本地 HTTP 服务打开。',['保存为 api.mjs，写另一个 main.mjs import 它。','Node 中传入返回 {ok:false,status:404} 的假 fetcher，捕获错误。','补充加载中、空结果、失败重试三个页面状态；用 finally 恢复按钮。'],['404 被识别为错误','模拟断网时显示失败而非空列表','能画出点击→请求→响应→渲染'],'fetch 收到 404 时应该怎样处理？',['检查 response.ok 并报告错误','当作成功数据渲染','无限重试'],0,'重复点击发送请求时，如何避免旧响应覆盖新响应？','https://developer.mozilla.org/zh-CN/docs/Web/API/Fetch_API/Using_Fetch');
guidedNew('javascript','js-12','独立重构与测试：从能用到能改','用一个纯函数模块作为独立验收，测试真实地调用生产函数。','单元测试验证小模块；集成测试验证模块连接；端到端测试验证用户完整流程。三个层次都需要失败案例。','// tasks.mjs\nexport function addTask(tasks, title) {\n const value=title.trim();\n if(!value) throw new Error("标题不能为空");\n return [...tasks,{title:value,done:false}];\n}\n// tasks.test.mjs（单独文件）\nimport {test} from "node:test";\nimport {strict as assert} from "node:assert";\nimport {addTask} from "./tasks.mjs";\ntest("空白标题不能添加",()=>assert.throws(()=>addTask([],"  ")));','分别保存两个文件；node --test tasks.test.mjs 执行真实函数。测试通过还不足以说明页面按钮、存储和部署正常。',['按注释拆成两个文件并运行 node --test。','增加重复标题规则，先写会失败的测试，再修改实现。','把模块接到上一课网页，验证刷新、空白输入和键盘操作。'],['先见到一个预期失败的测试','修改后测试通过','实际点击验证完整流程'],'什么能证明测试确实能发现某类 bug？',['故意引入对应错误后测试失败','测试文件行数很多','只检查函数存在'],0,'哪些测试应该在重构后仍然有效？','https://nodejs.org/api/test.html');

codeLesson('typescript','ts-01','类型标注：先理解它检查什么','TypeScript 在运行前检查 JavaScript 的类型约定。本网站使用真实编译器进行 strict 类型检查。','number 表示数字，string 表示文字。参数后的冒号声明期望类型，括号后的冒号声明返回类型。类型会在编译为 JavaScript 时擦除。','function double(n: number): number { return n * 2; }\nconsole.log(double(3));','传入 "3" 会产生类型错误；类型通过仍可能写成 n * 3，所以还需要行为测试。','实现 double(n: number): number，返回 n 的两倍。','function double(n: number): number { return n * 2; }','assert(double(3)===6);assert(double(0)===0);assert(double(-2)===-4);','加上参数类型和返回类型，然后故意传字符串观察诊断。','类型检查为什么发现不了乘 3 的业务错误？','typescript');
codeLesson('typescript','ts-02','对象类型与接口','接口描述对象应有的字段，不负责自动创建或校验网络数据。','interface 声明结构；可选字段用 ?；字段不存在时可能是 undefined。用 ?? 提供空值默认值。','interface User { name: string; nickname?: string }\nfunction display(u: User): string { return u.nickname ?? u.name; }','null/undefined 会触发 ?? 的右侧；空字符串不会。这和 || 的行为不同。','声明 User 接口，实现 display，优先 nickname，否则 name。','interface User { name: string; nickname?: string }\nfunction display(u: User): string { return u.nickname ?? u.name; }','assert(display({name:"林"})==="林");assert(display({name:"林",nickname:"小林"})==="小林");assert(display({name:"林",nickname:""})==="");','nickname?: string 表示可以省略。','可选字段、空字符串和 null 是一回事吗？','typescript');
codeLesson('typescript','ts-03','联合类型与收窄','数据可能是多种类型。先判断，再做该类型支持的操作。','string | number 表示二者之一；typeof 判断会让编译器在分支中缩小范围。不要用 any 让错误消失。','function size(value: string | number): number {\n return typeof value === "string" ? value.length : value;\n}','字符串有 length；number 没有。分支让每个操作都针对正确类型。','实现 size(value: string | number)，字符串返回长度，数字原样返回。','function size(value: string | number): number { return typeof value === "string" ? value.length : value; }','assert(size("abc")===3);assert(size(5)===5);assert(size("")===0);','使用 typeof value === "string"。','把所有数据断言为 string 为什么不能改变运行时真实值？','typescript');
codeLesson('typescript','ts-04','unknown：给外部输入设边界','接口声明不等于运行时验证。来自 JSON 的内容仍可能缺字段。','unknown 允许接收任何值，但使用前必须验证。typeof null 是 "object"，所以还要排除 null。','function isRecord(v: unknown): v is Record<string, unknown> {\n return typeof v === "object" && v !== null;\n}','v is ... 是类型守卫返回签名。检查要与声明一致，不可以随便返回 true 欺骗编译器。','实现 readName(value: unknown): string，只有非 null 对象且 name 是字符串才返回 name，否则抛出 Error。','function readName(value: unknown): string {\n if(typeof value!=="object" || value===null || !("name" in value) || typeof value.name!=="string") throw new Error("无效姓名");\n return value.name;\n}','assert(readName({name:"安"})==="安");for(const x of [null,3,{}, {name:3}]){let caught=false;try{readName(x)}catch{caught=true}assert(caught)}','用 in 判断属性存在，再检查属性类型。','如果还要求姓名非空，类型 string 能自动保证吗？','typescript');
codeLesson('typescript','ts-05','泛型：保留输入与输出的关系','不必为每种元素类型写一个重复函数。泛型把类型当参数传递。','T[] 是元素类型为 T 的数组；T | undefined 明确说明空数组没有首项。','function first<T>(items: T[]): T | undefined { return items[0]; }','编译器根据输入推断 T。输入 number[] 时，返回 number | undefined，而不是失去信息的 any。','实现 first<T>，返回首项或 undefined，不修改数组。','function first<T>(items: T[]): T | undefined { return items[0]; }','assert(first([4,5])===4);assert(first(["a"])==="a");assert(first([])===undefined);','返回类型要覆盖空数组。','为什么 first<T> 比 first(any[]) 更能帮助调用者？','typescript');
codeLesson('typescript','ts-06','可辨识联合：让状态完整','加载过程有等待、成功和失败。不要让三个互相矛盾的布尔值随意组合。','用同名字段 status 区分联合成员。switch 或 if 后编译器知道当前成员有哪些字段。','type Result = {status:"ok"; value:number} | {status:"error"; message:string};\nfunction show(r:Result):string { return r.status==="ok" ? String(r.value) : r.message; }','成功分支必须有 value；失败分支必须有 message。没有检查 status 就读取 value 会被编译器阻止。','声明 Result 并实现 show：成功返回数字的字符串，失败返回错误消息。','type Result = {status:"ok"; value:number} | {status:"error"; message:string};\nfunction show(r: Result): string { return r.status==="ok" ? String(r.value) : r.message; }','assert(show({status:"ok",value:0})==="0");assert(show({status:"error",message:"离线"})==="离线");','先判断 status，再访问成员专属字段。','增加 loading 状态时，如何用 never 做遗漏分支检查？','typescript');
codeLesson('typescript','ts-07','readonly 与可测试的更新','限制修改权限，让调用者清楚函数是否有副作用。','readonly number[] 表示函数不能通过这个引用修改数组；返回新数组可以保留输入。readonly 不是运行时冻结，也不是深层不可变。','function append(items: readonly number[], value:number): number[] { return [...items,value]; }','尝试 items.push(value) 会被检查器拒绝；展开创建新数组。仍要用运行时测试检查结果。','实现 append，不修改原数组，返回追加 value 后的新数组。','function append(items: readonly number[], value: number): number[] { return [...items,value]; }','const items=[1,2];const next=append(items,3);assert(items.length===2);assert(next!==items);assert(JSON.stringify(next)==="[1,2,3]");assert(append([],4)[0]===4);','不要使用类型断言绕过 readonly。','调用者拿到另一个可变引用时还能修改原数组吗？','typescript');
guidedNew('typescript','ts-08','本机工程：编译、测试与重构','浏览器小题之后，需要学习真实工程的模块、配置和构建。','tsconfig.json 记录编译规则；tsc --noEmit 只检查不输出；类型测试和行为测试是两种证据。依赖锁文件记录解析版本。','// tsconfig.json\n{"compilerOptions":{"strict":true,"target":"ES2020","module":"NodeNext","moduleResolution":"NodeNext","outDir":"dist"},"include":["src/**/*.ts"]}\n// 终端（不要放进 JSON 文件）\n// npm init -y\n// npm install --save-dev typescript@5.9.3\n// npx tsc --noEmit\n// npx tsc','把 JSON 内容保存为 tsconfig.json；命令在项目终端运行。浏览器练习使用 5.9.3；本机固定同版便于复现。',['在新目录初始化项目，建立 src/tasks.ts，从 JS 项目迁移 addTask。','启用 strict；先保留行为测试，再添加类型约定，不使用 any 消除全部报错。','运行编译和测试，把命令、输出、Node 版本记录到 README。'],['strict 编译通过','原有行为测试仍通过','故意传错误类型能看到诊断'],'tsc --noEmit 通过证明什么？',['在当前配置下类型检查通过','所有输入一定正确','服务器不会故障'],0,'哪些外部输入仍需运行时校验？','https://www.typescriptlang.org/tsconfig/');

const linuxLessons=[
 ['linux-01','认识终端与安全的练习目录','终端是输入指令的界面，Shell 是解释指令的程序，Linux 是操作系统内核。三者不是同一个东西。','Windows 用户先查看 WSL 官方安装说明，确认系统要求，再自行安装。已有 Linux 可直接使用。所有实验放在个人练习目录，先确认位置。','uname -a\npwd\nmkdir -p ~/codepath-labs\ncd ~/codepath-labs\npwd','uname 显示系统信息，pwd 显示当前绝对路径。~ 是当前用户主目录；mkdir -p 创建目录；cd 改变工作位置。',['在 WSL 或 Linux 终端运行 uname -a，记录环境。','创建并进入 codepath-labs；不要在系统目录练习。','记录终端、Shell、工作目录分别是什么。'],['确认是真实 Linux/WSL','pwd 指向自己的练习目录','保存环境记录'],'pwd 用于什么？',['查看当前工作目录','查看密码','删除文件'],0,'为什么同一条相对路径命令在不同目录会得到不同结果？','https://learn.microsoft.com/windows/wsl/install'],
 ['linux-02','文件路径、查看与复制','路径可以从 / 开始，也可以相对于当前目录。先学观察和复制，再学破坏性操作。','ls -la 查看隐藏项和权限；cat 适合短文本；less 分页浏览长文本；cp 复制，mv 移动或改名。带空格的路径要用引号。','mkdir -p notes backup\nprintf "hello Linux\\n" > notes/day1.txt\ncat notes/day1.txt\ncp notes/day1.txt backup/day1.txt\nls -la notes backup','> 覆盖目标文件，>> 才是追加。这里固定在新建练习目录使用。less 中 q 退出。',['确认 pwd 后运行示例，比较原件与副本。','创建带空格文件名并用引号读取。','用 diff notes/day1.txt backup/day1.txt 比较；修改副本后再次比较。'],['原件和副本可读取','能解释 /、. 和 ..','能识别覆盖与追加'],'哪种操作会覆盖已有文件内容？',['> 重定向','>> 追加','pwd'],0,'复制目录时需要什么参数？先查 man cp 再试。','https://www.gnu.org/software/coreutils/manual/'],
 ['linux-03','管道、重定向与退出状态','把一个命令的输出交给另一个处理，就是管道。','标准输入、标准输出、标准错误是三条通道；| 默认连接标准输出；$? 是上一条管道的退出状态，0 通常表示成功。','printf "INFO start\\nERROR timeout\\nINFO end\\n" > app.log\ngrep ERROR app.log | wc -l\ngrep MISSING app.log\nprintf "exit=%s\\n" "$?"','grep 找不到匹配一般返回 1，这并不等于程序崩溃。管道默认状态来自最后一个命令，set -o pipefail 可暴露前面的失败。',['筛选日志并统计错误行。','比较 >、2>、2>&1 的用途，分别保存正常与错误输出。','运行 false | true，再启用 set -o pipefail 重试，比较退出码。'],['正确统计一条 ERROR','解释标准错误','验证 pipefail 的差异'],'默认管道退出状态通常来自？',['最后一个命令','第一个命令','所有命令平均值'],0,'为什么日志里没有输出不一定代表成功？','https://www.gnu.org/software/bash/manual/html_node/Pipelines.html'],
 ['linux-04','用户、权限与最小授权','权限决定谁能读、写或执行。不会权限时，直接 chmod 777 会让问题扩大。','r=读，w=写，x=执行；权限分别适用于所有者、同组、其他人。目录的 x 表示可以进入和访问已知路径。','id\nprintf "仅供练习\\n" > private.txt\nchmod 600 private.txt\nls -l private.txt','600 表示所有者可读写，其他人无权限。不要把真实密钥写进练习文件；这只是演示权限位。',['记录 id 与文件所属用户。','把练习文件设为 600，用 ls -l 解释每一组权限。','给自己的脚本增加 u+x，解释为什么不需要 777。'],['正确解释 rwx','使用最小权限','未修改系统目录权限'],'600 给谁读写权限？',['仅所有者','所有人','只有其他用户'],0,'文件权限正确为什么仍可能泄漏？考虑备份、日志和仓库。','https://www.gnu.org/software/coreutils/manual/html_node/File-permissions.html'],
 ['linux-05','进程、信号与温和停止','运行中的程序是进程。先知道它是谁，再发停止信号。','PID 是进程编号；ps 查看状态；kill 默认发送 TERM 请求退出；KILL 不给程序清理机会。','sleep 120 &\nlab_pid=$!\nps -p "$lab_pid" -o pid,comm\nkill -TERM "$lab_pid"','& 放到后台；$! 是最近后台进程 PID。这里只停止自己刚创建的 sleep，不随意处理其他进程。',['启动示例并确认 PID 和命令。','发 TERM 后用 ps 验证已退出。','解释退出清理可能包括哪些内容。'],['识别自己启动的 PID','用 TERM 停止并复查','能区分 TERM 和 KILL'],'为什么先用 TERM？',['允许程序处理退出和清理','它一定立即结束所有进程','它会自动备份全部文件'],0,'后台任务和长期受管理服务有什么区别？','https://www.gnu.org/software/bash/manual/html_node/Signals.html'],
 ['linux-06','网络排障：从端口到 HTTP','网页打不开不一定是代码逻辑错误。逐层核对地址、端口和响应。','127.0.0.1 表示本机；监听端口让服务接收连接；HTTP 状态码说明请求处理结果。连接失败和 404 属于不同层。','python3 -m http.server 8000 --bind 127.0.0.1\n# 另一个终端：\ncurl -i http://127.0.0.1:8000/\nss -ltn','服务仅绑定本机；Ctrl+C 停止。curl -i 显示响应头；ss -ltn 列出监听 TCP 端口。不要将包含私密文件的目录公开。',['在只含练习文件的目录启动服务。','分别访问存在与不存在的路径，记录 200/404。','停止服务后再访问，比较连接错误与 HTTP 错误。'],['看到本地 HTTP 响应','区分 404 与连接失败','停止后确认端口不再监听'],'404 通常说明什么？',['已收到 HTTP 响应但资源未找到','TCP 一定无法连接','DNS 一定失败'],0,'本机能访问但远端不能，应该继续检查哪几层？','https://docs.python.org/3/library/http.server.html'],
 ['linux-07','包管理、虚拟环境与可复现','系统依赖和项目依赖分开，才能避免两个项目互相干扰。','apt 是部分发行版的系统包管理器；其他发行版不同。venv 为 Python 项目隔离依赖。锁定版本帮助重建，但不能保证所有平台完全一致。','python3 -m venv .venv\nsource .venv/bin/activate\npython -m pip --version\npython -m pip freeze > requirements.txt\ndeactivate','若 venv 缺失，查看发行版说明安装相应组件；不要不理解就使用 sudo pip。pip --version 会显示路径，帮助确认是否在虚拟环境。',['记录 /etc/os-release 并确认发行版。','创建 venv，比较激活前后的 which python 或 command -v python。','在第二个练习目录重建环境，记录依赖和版本。'],['确认项目 Python 路径','生成依赖记录','能说明系统包与项目包区别'],'虚拟环境主要解决什么？',['隔离 Python 项目依赖','隔离整台电脑网络','自动审计所有包'],0,'为什么 requirements 中的版本记录不等于完整供应链审计？','https://docs.python.org/3/library/venv.html'],
 ['linux-08','Shell 脚本、引用与失败传播','把重复命令写成脚本，但必须能处理文件名空格和失败情况。','#!/usr/bin/env bash 指定解释器；"$变量" 保留空格；set -euo pipefail 帮助暴露部分失败，但不是可靠性的全部保证。','#!/usr/bin/env bash\nset -euo pipefail\nsource_file="${1:?请提供源文件}"\n[ -f "$source_file" ] || { echo "不是文件" >&2; exit 1; }\nmkdir -p backup\ncp -- "$source_file" backup/\nprintf "已备份：%s\\n" "$source_file"','${1:?...} 检查第一个参数；-- 结束选项解析，避免文件名以 - 开头被当成选项。显式验证仍不可省。',['保存 backup.sh 并 bash backup.sh "notes/day1.txt"。','测试缺参数、不存在路径、空格文件名，检查退出码。','修改为保留时间戳副本，避免覆盖旧备份。'],['成功场景通过','三个失败边界有记录','所有路径变量有双引号'],'为什么引用 "$source_file"？',['保留一个完整参数，避免空格拆分','把它变成管理员命令','自动检查文件内容'],0,'set -e 在条件语句中的例外为什么值得查官方手册？','https://www.gnu.org/software/bash/manual/'],
 ['linux-09','服务与日志：按证据定位故障','长期服务要由进程管理器管理，不能只依靠一个开着的终端。','systemd 用 unit 描述启动命令、目录和重启策略。WSL/容器不一定启用 systemd；先 ps -p 1 -o comm= 检查。','ps -p 1 -o comm=\n# 仅在启用了 systemd 且已有个人服务时：\n# systemctl --user status codepath.service\n# journalctl --user -u codepath.service -n 50 --no-pager','status 告诉当前状态；journalctl 查看历史事件。错误日志应包含时间、请求标识、异常类型，避免记录凭据。',['检查 PID 1，记录当前环境是否支持 systemd。','支持时用个人 user unit 管理练习服务，明确 WorkingDirectory 和绝对 ExecStart；否则记录替代进程管理方案。','故意设错工作目录，观察日志，恢复后验证 HTTP。'],['记录环境支持情况','保存失败与修复的日志证据','恢复后验证请求'],'定位服务失败优先依据什么？',['实际状态、启动命令和错误日志','不断重装全部依赖','只看浏览器空白'],0,'Restart=always 为什么可能放大快速失败循环？','https://www.freedesktop.org/software/systemd/man/latest/systemd.service.html'],
 ['linux-10','毕业实验：备份、恢复与部署排障','验收一个小服务：能启动，也能在故障后恢复，并解释每一步。','可用的备份必须实际恢复验证。部署过程应记录依赖、配置、健康检查与回滚点；日志能串联一次请求。','tar -czf lab-backup.tar.gz notes\nmkdir -p restore-check\ntar -xzf lab-backup.tar.gz -C restore-check\ndiff -r notes restore-check/notes','归档只包含练习 notes。恢复到新目录再比较，避免覆盖原件。真实备份还需权限、加密、保留策略和异地验证。',['部署自己的 FastAPI 练习服务并仅绑定本机。','分别制造端口冲突、缺环境变量、错误路径，记录排障过程。','恢复备份到新目录，执行接口测试；提交 README 和一张进程/端口/依赖结构图。'],['三种故障都定位并修复','备份恢复比较一致','能按 README 在新目录复现'],'备份成功的最低验证是？',['恢复到新目录并比较','文件名里有 backup','压缩命令没有明显输出'],0,'恢复时间目标和可接受数据丢失时间应如何约定？','https://www.gnu.org/software/tar/manual/']
];
for(const row of linuxLessons)guidedNew('linux',...row);

function agentLesson(id,title,intro,concept,example,explain,task,solution,test,hint,reflection){codeLesson('agent-systems',id,title,intro,concept,example,explain,task,solution,test,hint,reflection,'python');LESSONS.at(-1).starter='# '+task+'\n';}
agentLesson('as-01','智能体到底是什么：观察、状态与行动','先不接大模型：能根据观察选择行动的程序，就能帮助我们理解智能体的基本循环。','观察是输入；状态保留过去的信息；策略选择行动；环境产生新观察。规则型、规划型和学习型是不同决策方法，不等于能力等级。','def thermostat(temp):\n    return "heat" if temp < 20 else "idle"','这个恒温器是简单反应型策略：只依赖当前温度，没有记忆，也没有模型调用。','实现 action(temp)，低于 18 返回 heat，高于 26 返回 cool，其余返回 idle。','def action(temp):\n    if temp < 18: return "heat"\n    if temp > 26: return "cool"\n    return "idle"','assert action(17)=="heat"\nassert action(18)=="idle"\nassert action(26)=="idle"\nassert action(27)=="cool"','先写两个边界比较，再写默认分支。','如果温度传感器失效，应沿用旧状态、停止还是报警？由谁决定？');
agentLesson('as-02','带状态的架构与 BDI 思路','任务助理需要记住目标和已发生的事。BDI 是用信念、愿望、意图描述决策的一种思路。','信念是对环境的当前判断；愿望是候选目标；意图是承诺执行的目标。信息可能过时，因此要重新检查。下面用状态机演示，不是完整 BDI 实现。','transitions = {("idle","start"):"working", ("working","finish"):"done"}','用 (状态,事件) 作为键，明确列出合法转换，避免任意事件改变任务状态。','实现 step(state,event)，按示例转换；其他组合返回原状态。','def step(state,event):\n    transitions={("idle","start"):"working",("working","finish"):"done"}\n    return transitions.get((state,event),state)','assert step("idle","start")=="working"\nassert step("working","finish")=="done"\nassert step("idle","finish")=="idle"\nassert step("done","start")=="done"','用字典 get(key, default)。','事件迟到、重复到达时为什么需要状态约束？');
agentLesson('as-03','消息协议与关联标识','两个智能体不能只互相发一段自由文本，否则难以定位这段回复属于哪个请求。','消息信封至少说明发送者、接收者、类型、request_id、payload。correlation_id 关联请求与响应；结构校验与业务校验分开。','message={"from":"planner","to":"worker","request_id":"r1","type":"task","payload":{"topic":"日志"}}','这些字段是教学协议约定，不是通用行业协议标准。真实系统还需要鉴权、版本、超时和大小限制。','实现 valid(message)，只有 dict，且 request_id、from、to、type 为非空字符串，payload 为 dict 才返回 True。','def valid(message):\n    if not isinstance(message,dict): return False\n    return all(isinstance(message.get(k),str) and bool(message[k].strip()) for k in ["request_id","from","to","type"]) and isinstance(message.get("payload"),dict)','assert valid({"request_id":"r1","from":"a","to":"b","type":"task","payload":{}})\nassert not valid({})\nassert not valid(None)\nassert not valid({"request_id":" ","from":"a","to":"b","type":"task","payload":{}})','先确认是字典，再访问字段；使用 all。','合法 JSON 能否保证消息语义可信？怎样验证发送者身份？');
agentLesson('as-04','同步、异步与去重','同步调用等待回复；异步消息允许稍后处理，但也引入重复、乱序和延迟。','至少一次投递可能重复送达；消费者用稳定事件 ID 去重。下面演示单进程去重；真实系统需要把处理结果与去重记录原子提交。','seen=set()\nfor event_id in ["a","a","b"]:\n    if event_id not in seen:\n        seen.add(event_id)\n        print(event_id)','set 保存见过的 ID。只在内存里保存时，进程重启会丢失记录，不能宣称恰好一次处理。','实现 unique_events(events)，按首次出现顺序返回 ID 列表。','def unique_events(events):\n    seen=set(); result=[]\n    for event in events:\n        if event not in seen:\n            seen.add(event); result.append(event)\n    return result','assert unique_events(["a","b","a"])==["a","b"]\nassert unique_events([])==[]\nassert unique_events(["a","a"])==["a"]','同时使用 set 做查询、list 保留顺序。','如果业务已执行但去重记录尚未提交就崩溃，会发生什么？');
agentLesson('as-05','协作拓扑：主管、流水线与黑板','主管分配任务；流水线按阶段传递结果；黑板让成员共享任务状态。选型取决于任务依赖与失败边界。','集中式便于追踪但有单点；去中心化降低中心依赖但更难协调。发布订阅解耦发送者和接收者，但不保证业务流程正确。','board={"research":"done","draft":"waiting"}\nready = board["research"] == "done"','共享状态必须规定谁能写、何时写，以及并发更新冲突如何解决。下面先用依赖判定代替真实并发。','实现 ready(dependencies, completed)，所有依赖都已完成才返回 True；无依赖返回 True。','def ready(dependencies,completed):\n    return all(item in completed for item in dependencies)','assert ready(["a","b"],{"a","b"})\nassert not ready(["a","b"],{"a"})\nassert ready([],set())','all([]) 为 True。','多个成员同时修改同一任务状态，版本号或事务怎样帮忙？');
agentLesson('as-06','任务分配：合约网的简化竞价','合约网常用“发布任务—投标—选择—授予”表达协作。报价不等于可信能力证明。','本练习只实现选择最低成本的候选者，不是完整合约网协议。要先过滤不可用、过期或不合格的报价，再按确定规则打破平局。','bids=[{"agent":"A","cost":3,"available":True},{"agent":"B","cost":2,"available":False}]','选择策略必须可解释；最低成本可能不等于最高质量，真实场景要把能力、期限和质量约束纳入。','实现 choose(bids)，从 available 为 True 的报价中按 cost、agent 排序选 agent；无可用报价返回 None。','def choose(bids):\n    usable=[b for b in bids if b.get("available") is True]\n    return min(usable,key=lambda b:(b["cost"],b["agent"]))["agent"] if usable else None','assert choose([]) is None\nassert choose([{"agent":"B","cost":2,"available":True},{"agent":"A","cost":2,"available":True}])=="A"\nassert choose([{"agent":"X","cost":0,"available":False}]) is None','min 的 key 可以返回元组，实现稳定平局规则。','如何验证中标者确实完成任务？超时后如何再分配且避免重复执行？');
agentLesson('as-07','规划算法：DAG 与拓扑排序','有些任务必须先做 A，再做 B。把依赖画成有向图，再决定执行次序。','DAG 是无环有向图。每次选没有未完成依赖的任务；如果还有任务但一个都选不出，说明有环或缺少依赖。','dependencies={"test":["code"],"code":["design"],"design":[]}','这是拓扑排序的一种直观实现。排序不是智能推理，它只保证给定依赖的先后关系。','实现 plan(deps) 返回合法顺序；循环依赖或缺失依赖抛出 ValueError。','def plan(deps):\n    done=[]\n    while len(done)<len(deps):\n        choices=sorted(k for k,v in deps.items() if k not in done and all(d in done for d in v))\n        if not choices: raise ValueError("循环或缺失依赖")\n        done.append(choices[0])\n    return done','assert plan({"b":["a"],"a":[]})==["a","b"]\nassert plan({})==[]\nfor bad in [{"a":["b"],"b":["a"]},{"a":["missing"]}]:\n    try: plan(bad)\n    except ValueError: pass\n    else: raise AssertionError("必须拒绝无法满足的依赖")','每轮选已满足全部依赖的一个节点。','任务执行失败时，已经运行的下游步骤应该怎样处理？');
agentLesson('as-08','搜索算法：最短路径与启发式','规划路线时，需要比较多条可选路径。先学习无权图的广度优先搜索。','BFS 按边数逐层探索，适合每条边成本相同；Dijkstra 处理非负权重；A* 使用启发式，最优性依赖相应条件，不能随便猜一个估价就保证最短。','from collections import deque\nqueue=deque([("start",0)])','队列先进先出；访问集合避免在环里无限绕行。距离表示走过的边数。','实现 distance(graph,start,goal)，返回无权图最少边数，不可达返回 None。','from collections import deque\ndef distance(graph,start,goal):\n    queue=deque([(start,0)]); seen={start}\n    while queue:\n        node,d=queue.popleft()\n        if node==goal: return d\n        for nxt in graph.get(node,[]):\n            if nxt not in seen:\n                seen.add(nxt); queue.append((nxt,d+1))\n    return None','assert distance({"a":["b","c"],"b":["c"]},"a","c")==1\nassert distance({},"a","a")==0\nassert distance({"a":["a"]},"a","b") is None','入队时记录 seen，防止重复加入。','为什么每条边耗时不同后，最少边数不等于最短时间？');
agentLesson('as-09','学习算法：一次 Q 值更新','强化学习通过奖励更新行动价值。这里学会公式，不把一个小公式误认为训练完成的智能体。','Q(s,a) 估计在状态 s 采取动作 a 的长期价值。更新为 old + alpha × (reward + gamma × next_max − old)。alpha 是学习率，gamma 是折扣。','old=2; reward=3; alpha=0.5; gamma=0.9; next_max=4\nnew=old+alpha*(reward+gamma*next_max-old)','即时奖励和未来价值一起形成目标；终止状态的 next_max 应是 0。多智能体同时学习会使环境从单个成员视角变得不稳定。','实现 update(old,reward,next_max,alpha,gamma)，按公式返回新值。','def update(old,reward,next_max,alpha,gamma):\n    return old+alpha*(reward+gamma*next_max-old)','assert abs(update(2,3,4,0.5,0.9)-4.3)<1e-9\nassert update(2,3,4,0,0.9)==2\nassert update(2,3,0,1,0.9)==3','用括号先计算 TD 误差，再乘学习率。','奖励只看速度时，成员会不会牺牲质量？如何设计评估？');
agentLesson('as-10','投票、共识与不可信成员','多个智能体同意一件事，不代表事实正确，尤其是它们共享模型和资料时。','多数投票是聚合方法，不等于分布式一致性协议，也不等于拜占庭容错。这里要求严格过半；平局或无票返回 None。','votes=["approve","approve","reject"]','多数票可以做非关键建议聚合；财务授权、外部写入等应使用明确权限和人工审批。','实现 majority(votes)，某值次数严格超过总数一半才返回该值，否则 None。','from collections import Counter\ndef majority(votes):\n    for value,count in Counter(votes).items():\n        if count>len(votes)/2: return value\n    return None','assert majority(["a","a","b"])=="a"\nassert majority(["a","b"]) is None\nassert majority([]) is None\nassert majority(["a","b","c"]) is None','使用 Counter 统计；不要把最多票误当成过半。','共同错误来源会让三票比一票更可靠吗？应如何增加独立证据？');
guidedNew('agent-systems','as-11','LLM 工具循环：预算、权限与可观测性','LLM 可以建议下一步调用哪个工具，但执行权限必须由程序控制。','循环包含观察、模型建议、参数验证、授权、工具执行、结果回填、停止判断。模型输出是待验证数据；工具结果也是不可信外部输入。','MAX_STEPS = 5\nALLOWED_TOOLS = {"search_docs", "read_status"}\n# 每轮：验证结构 -> 白名单 -> 权限 -> 超时 -> 记录 request_id\n# 达到步数、金额或时间预算时停止\n# 写入外部系统前暂停并等待明确授权','固定工作流适合已知步骤；智能体适合需要动态选择的步骤。先做单智能体基线，再用实验判断多智能体是否值得额外成本。',['画出一次请求的状态转换图，标出失败出口。','用假模型依次返回未知工具、错误参数、循环建议，验证都能受控停止。','记录每轮耗时、调用数、成本估算和结果来源，不记录密钥。'],['未知工具不会执行','循环触发最大步数限制','外部写入有独立授权点'],'模型说“已获授权”意味着？',['仍需由程序核验真实授权状态','可以直接执行任何工具','工具白名单失效'],0,'超时后重试有副作用的工具为什么需要幂等键？','https://www.anthropic.com/engineering/building-effective-agents');
guidedNew('agent-systems','as-12','应用选型与对照实验','用客服分流、资料整理、代码审查或仓储调度场景检验架构，而不是为多智能体而多智能体。','先定义任务成功标准，再比较规则流程、单智能体、多智能体。记录正确率、延迟、成本、人工接管次数；使用同一测试集和预算。','case_id,input,expected,system,success,latency_ms,calls\n1,"缺订单号",ask_order_id,workflow,true,12,0\n2,"工具超时",controlled_failure,single_agent,true,3200,1','示例数据只是表格格式，不是真实性能结果。关键问题是多出来的成员是否改善可测量的目标。',['选一个场景，写 10 个含失败边界的用例和可判定预期。','分别实现固定流程与单智能体基线，再考虑加入第二成员。','故意让一个成员超时、重复消息和输出错误结构，记录恢复策略。'],['同一组用例对照三种设计','报告成本与失败案例','解释为何保留或放弃多智能体'],'如何证明多智能体值得使用？',['同条件实验显示目标改善且代价可接受','成员越多越好','回答更长'],0,'如果质量不变但成本翻倍，应当怎样调整架构？','https://www.anthropic.com/engineering/building-effective-agents');
const sourceOverrides={"as-06":"https://www.fipa.org/specs/fipa00029/","as-07":"https://docs.python.org/3/library/graphlib.html","as-08":"https://docs.python.org/3/library/collections.html#collections.deque","as-09":"https://www.incompleteideas.net/book/bookdraft2018mar21.pdf","as-10":"https://raft.github.io/"};
// Bridge from the first output statement to the function-based exercises.
Object.assign(LESSONS.find(l=>l.id==='js-02'),{
 title:'变量与第一个函数：给计算起名字',
 intro:'先给价格和数量起名字，再把计算装进可以重复使用的函数。读完这课，你就能理解后续练习里的参数和 return。',
 concept:'const 保存不重新赋值的名称，let 保存允许重新赋值的名称。数值 3 与字符串 "3" 不同。函数是一组可重复调用的指令：function 后面是函数名，圆括号里的参数接收输入，花括号是函数体，return 把结果交还给调用它的地方。',
 example:'const price = 8;\nlet count = 2;\n\nfunction total(price, count) {\n  return price * count;\n}\n\nconst result = total(price, count);\nconsole.log(result);',
 explain:'第 1、2 行保存数字；function 这一段只是定义，还没计算。调用 total(price, count) 时，外面的 8 和 2 传入函数的两个参数；return 返回 16，result 接住它；最后 console.log 显示结果。函数参数属于函数自己的作用域，和外面同名的变量不是同一个变量。只写 console.log 不会替代 return：测试会调用你的函数并检查返回值。',
 steps:['先照示例定义 total(price, count)，用 return 返回乘积。','调用 total(8, 2) 并显示，应该得到 16；再试 total(5, 0)，应该得到 0。','点击运行，让检查器验证其他输入；把 return 去掉，观察失败原因，再修复。'],
 starter:'function total(price, count) {\n  // 用 return 把乘积交还给调用者\n}\n\nconsole.log(total(8, 2));'
});
for(const l of LESSONS)if(sourceOverrides[l.id])l.source=sourceOverrides[l.id];
const trackOrder=['python','structures','sql','engineering','linux','javascript','typescript','fastapi','java','springboot','springai','agent','multi','agent-systems','source','review','systems'];
TRACKS.sort((a,b)=>trackOrder.indexOf(a.id)-trackOrder.indexOf(b.id));

